type OptionExtras = Pick<
  BaseComponentOptionMeta,
  | 'enabledWhen'
  | 'visibleWhen'
  | 'conflicts'
  | 'requires'
  | 'accessibilityImpact'
  | 'recordFields'
  | 'recordItemLabel'
  | 'recordHasId'
  | 'inspectorGroup'
>;

type OptionInput = readonly [
  id: string,
  axis: BaseComponentOptionAxis,
  disposition: BaseComponentOptionDisposition,
  control: BaseComponentOptionControl,
  defaultValue: unknown,
  values?: readonly unknown[],
  propPath?: string,
  extras?: Partial<OptionExtras>,
];

type SectionDefinition = {
  id: string;
  label: string;
  family: string;
  kind: BaseComponentMeta['kind'];
  maturity: BaseComponentMeta['maturity'];
  purpose: string;
  avoid: string;
  anatomy: readonly [required: readonly string[], optional: readonly string[]];
  antiOptions: readonly string[];
  evidenceRefs: readonly string[];
  options: readonly OptionInput[];
};

