export const CATALOG_SECTION_COMPONENTS = ALL_SECTION_DEFINITIONS.map((definition) => {
  const optionIds = definition.options.map(([id]) => id);
  const requiredScenarios = definition.options
    .filter(([, , disposition]) => disposition === 'scenario')
    .map(([id]) => id);
  return {
    id: definition.id,
    family: definition.family,
    kind: definition.kind,
    maturity: definition.maturity,
    publicExportIds: KNOWN_PUBLIC_EXPORTS_BY_SECTION[definition.id] ?? [],
    useWhen: [definition.purpose],
    avoidWhen: [definition.avoid],
    anatomy: {
      required: definition.anatomy[0],
      optional: definition.anatomy[1],
    },
    optionIds,
    requiredScenarios,
    requiredTests: [`${definition.id}.metadata`, `${definition.id}.option-liveness`],
    antiOptions: definition.antiOptions,
  } satisfies BaseComponentMeta;
});

export const CATALOG_SECTION_EXPORTS = Object.entries(KNOWN_PUBLIC_EXPORTS_BY_SECTION)
  .flatMap(([componentId, exportIds]) =>
    exportIds.map((exportId) => ({
      exportId,
      classification: 'public-composite',
      componentId,
    } satisfies BaseComponentExportMeta)),
  );

export const CATALOG_SECTION_DEMOS = ALL_SECTION_DEFINITIONS.map((definition) => {
  const component = CATALOG_SECTION_COMPONENTS.find(({ id }) => id === definition.id)!;
  return {
    id: `${definition.id}.primary`,
    componentId: definition.id,
    sectionId: definition.id,
    anchor: definition.id,
    primary: true,
    scenarios: component.requiredScenarios,
  } satisfies BaseComponentDemoMapping;
});

