const getOptionLivenessTestFile = (definition: SectionDefinition): string => {
  const testFile =
    OPTION_LIVENESS_TEST_FILE_BY_FAMILY[definition.family]
    ?? GENERAL_OPTION_LIVENESS_TEST_FILE_BY_SECTION[definition.id];
  if (!testFile) {
    throw new Error(`Missing option-liveness test file for ${definition.id}`);
  }
  return testFile;
};

export const CATALOG_SECTION_TESTS = ALL_SECTION_DEFINITIONS.flatMap((definition) => [
  {
    id: `${definition.id}.metadata`,
    componentId: definition.id,
    testId: `${definition.id}.metadata`,
    testFile: 'src/features/base-components/catalog/__tests__/baseComponentCatalog.test.ts',
  },
  {
    id: `${definition.id}.option-liveness`,
    componentId: definition.id,
    testId: `${definition.id}.option-liveness`,
    testFile: getOptionLivenessTestFile(definition),
  },
] satisfies BaseComponentTestMapping[]);
